// @name Transit departures
// @background #0f172a
// @refresh 60
// The next departures from one or two stops, as a station board: the line in
// its color, where it goes, and the minutes until it leaves. A live
// prediction has the live mark, a timetable time is drawn quieter with a
// clock, a delay is a chip beside the time, and a canceled trip says so.
//
// Where the departures come from (the Provider setting):
// - MBTA, Entur (all of Norway) and TfL: each agency's own JSON API, no key,
//   a small answer for one stop (providers.ts). The same on every frame.
// - Any GTFS-Realtime TripUpdates feed: the agency's protobuf, decoded here
//   as it streams in, keeping only the stops asked for (gtfsrt.ts, feed.ts).
//   A feed holds times but no names: the Lines setting gives each route its
//   name, color and destinations.
//
// The last good departures are kept on disk (the private `board` field). An
// error says what went wrong and keeps them, counted down from the clock.
import { readFeed, headersOf } from './feed'
import { parseLines, type Departure } from './gtfsrt'
import { entur, enturStopId, mbta, tfl } from './providers'
import { agoText, clockText, delayText, inkOn, INKS, lightness, MINUTE, namesOf, nearestInk, upcoming, whenText, type Board, type Stop } from './board'

const PROVIDERS: Record<string, string> = { mbta: 'MBTA', entur: 'Entur', tfl: 'TfL', gtfsrt: 'GTFS-Realtime' }

// Not asked again sooner than this, whatever renders the scene (a tap, a
// window coming forward): the refresh interval sets the pace.
const FETCH_GAP = 25 * 1000

type Config = {
  provider: string
  stops: string[]
  labels: string[]
  feedUrl: string
  feedHeader: string
  lines: string
  only: string[]
  walk: number
}

// A stop as it is typed: "70075, 70076", or with a name of your own before
// an equals sign, "Park Street = 70075, 70076".
function stopOf(text: any): { label: string; query: string } {
  const typed = String(text ?? '').trim()
  const at = typed.indexOf('=')
  return at > 0 ? { label: typed.slice(0, at).trim(), query: typed.slice(at + 1).trim() } : { label: '', query: typed }
}

function configOf(app: FrameOSApp): Config {
  const s = app.state
  const provider = PROVIDERS[s.provider] ? String(s.provider) : 'mbta'
  const stops = [stopOf(s.stop), stopOf(s.stop2)].filter((stop) => stop.query)
  return {
    provider,
    stops: stops.map((stop) => stop.query),
    labels: stops.map((stop) => stop.label),
    feedUrl: String(s.feedUrl ?? '').trim(),
    feedHeader: String(s.feedHeader ?? ''),
    lines: String(s.lines ?? ''),
    only: namesOf(s.only),
    walk: Math.max(0, Math.min(120, Number(s.walk) || 0)),
  }
}

// What the departures were fetched for: another provider, stop or feed is
// another board, and the last one's departures are not shown for it.
const keyOf = (c: Config) => [c.provider, c.stops.join('/'), c.provider === 'gtfsrt' ? `${c.feedUrl}|${c.lines}` : ''].join('|')

// What a setting that is missing or wrong says, else ''.
function setupProblem(c: Config): string {
  if (c.provider === 'gtfsrt' && !/^https?:\/\//.test(c.feedUrl)) return 'Add the address of a GTFS-Realtime TripUpdates feed in the scene settings.'
  if (!c.stops.length) {
    if (c.provider === 'mbta') return 'Add a stop in the scene settings: its id from mbta.com/stops (place-pktrm is Park Street).'
    if (c.provider === 'entur') return 'Add a stop in the scene settings: its name ("Jernbanetorget") or its NSR id.'
    if (c.provider === 'tfl') return 'Add a stop in the scene settings: its id from tfl.gov.uk (940GZZLUKSX is King\'s Cross St. Pancras).'
    return 'Add the stop ids the feed uses in the scene settings (from the agency\'s stops.txt), a few with commas.'
  }
  return ''
}

const loadBoard = (app: FrameOSApp, key: string): Board | null => {
  const kept = app.state.board
  return kept && typeof kept === 'object' && kept.key === key && Array.isArray(kept.stops) ? (kept as Board) : null
}
const saveBoard = (board: Board) => frameos.setState('board', board as any)

// Since when a feed has been coming in, on this interpreter (a Pi, an ESP32
// that stays awake): no second request while one streams.
let streamingSince = 0

// Asks the provider again. JSON providers answer within this call; a feed may
// answer later, and then draws the scene again by itself.
function refresh(app: FrameOSApp, c: Config, kept: Board | null, now: number): Board & { loading?: boolean } {
  const key = keyOf(c)
  const base: Board = kept || { key, at: 0, tried: 0, stops: [], error: '' }
  const failed = (error: string, when: number): Board => ({ ...base, key, tried: when, error })
  if (c.provider !== 'gtfsrt') {
    try {
      const names = { ...(base.names || {}) }
      const stops: Stop[] = c.stops.map((stop) => {
        if (c.provider === 'mbta') return mbta(stop, now)
        if (c.provider === 'tfl') return tfl(stop, now)
        // Entur: a name is looked up once and kept with the board.
        const found = names[stop] || (names[stop] = enturStopId(stop))
        const board = entur(found.id, now)
        return { name: found.name || board.name, list: board.list }
      })
      const board: Board = { key, at: now, tried: now, stops: stops.map((s) => ({ name: s.name, list: s.list.slice(0, 24) })), error: '', names }
      saveBoard(board)
      return board
    } catch (e) {
      const board = failed(String((e as any)?.message || e), now)
      saveBoard(board)
      return board
    }
  }
  if (streamingSince && now - streamingSince < 90 * 1000) return { ...base, loading: true }
  streamingSince = now
  let inCall = true
  let answered: Board | null = null
  const lines = parseLines(c.lines)
  const stopIds = c.stops.map((stop) => stop.split(',').map((id) => id.trim()).filter(Boolean))
  readFeed(app, c.feedUrl, headersOf(c.feedHeader), stopIds, lines, now, (scan, error) => {
    streamingSince = 0
    const when = Date.now()
    const board: Board = scan
      ? {
          key,
          at: when,
          tried: when,
          error: '',
          feedTime: scan.feedTime * 1000,
          // A feed names no stop: the first id, until the stop is given a name.
          stops: scan.stops.map((s, i) => ({ name: `Stop ${stopIds[i][0]}${stopIds[i].length > 1 ? ` +${stopIds[i].length - 1}` : ''}`, list: s.list.slice(0, 24) })),
        }
      : failed(error, when)
    saveBoard(board)
    if (inCall) answered = board
    else frameos.dispatch('render')
  })
  inCall = false
  if (answered) return answered
  // Coming in between renders: the last good ones until then.
  const waiting: Board = { ...base, key, tried: now }
  saveBoard(waiting)
  return { ...waiting, loading: true }
}

// ---------------------------------------------------------------- looks

type Theme = {
  page: string
  ink: string
  muted: string
  rule: string
  badge: string
  badgeInk: string
  live: string
  late: string
  early: string
  gone: string
  chipLate: string
  chipEarly: string
  bar: string
  barError: string
  paper: boolean
  high: boolean
}

const DARK: Theme = {
  page: '#0f172a', ink: '#f8fafc', muted: '#94a3b8', rule: '#1e293b', badge: '#334155', badgeInk: '#ffffff',
  live: '#34d399', late: '#fbbf24', early: '#38bdf8', gone: '#fb7185',
  chipLate: 'bg-[#fbbf24] text-[#111827]', chipEarly: 'bg-[#38bdf8] text-[#111827]',
  bar: 'text-[#94a3b8]', barError: 'bg-[#7f1d1d] text-[#fee2e2]', paper: false, high: false,
}
const LIGHT: Theme = {
  page: '#f8fafc', ink: '#0f172a', muted: '#64748b', rule: '#e2e8f0', badge: '#cbd5e1', badgeInk: '#0f172a',
  live: '#059669', late: '#d97706', early: '#0284c7', gone: '#e11d48',
  chipLate: 'bg-[#f59e0b] text-[#111827]', chipEarly: 'bg-[#0ea5e9] text-white',
  bar: 'text-[#64748b]', barError: 'bg-[#fee2e2] text-[#7f1d1d]', paper: false, high: false,
}
// No color on the panel (black and white, greys): black on white, every
// badge black, a delay an inverted chip.
const HIGH: Theme = {
  page: '#ffffff', ink: '#000000', muted: '#000000', rule: '#000000', badge: '#000000', badgeInk: '#ffffff',
  live: '#000000', late: '#000000', early: '#000000', gone: '#000000',
  chipLate: 'bg-black text-white', chipEarly: 'bg-white text-black border-2 border-black',
  bar: 'text-black', barError: 'bg-black text-white', paper: true, high: true,
}
// Color e-paper: the same page with the lines, the live mark and the chips in
// solid inks.
const INK: Theme = {
  ...HIGH,
  live: INKS.green, late: INKS.red, early: INKS.blue, gone: INKS.red,
  chipLate: `bg-[${INKS.red}] text-white`, chipEarly: `bg-[${INKS.blue}] text-white`,
  barError: `bg-[${INKS.red}] text-white`, high: false,
}

function themeOf(app: FrameOSApp): Theme {
  const mode = app.state.contrast || 'auto'
  if (mode === 'high' || (mode === 'auto' && app.frame.color === false)) return HIGH
  if (mode === 'auto' && app.frame.paper === true) return INK
  return app.state.look === 'light' ? LIGHT : DARK
}

// A line's badge colors on this panel, and a ring around one that would
// vanish into the page (the Northern line's black on the dark board).
function badgeOf(t: Theme, d: Departure): { back: string; ink: string; ring: string } {
  if (t.high) return { back: t.badge, ink: t.badgeInk, ring: '' }
  if (!d.color) return { back: t.paper ? INKS.black : t.badge, ink: t.paper ? '#ffffff' : t.badgeInk, ring: '' }
  if (t.paper) {
    const back = nearestInk(d.color)
    return { back, ink: back === INKS.yellow ? '#000000' : '#ffffff', ring: '' }
  }
  const near = Math.abs(lightness(d.color) - lightness(t.page.slice(1))) < 40
  return { back: `#${d.color}`, ink: d.text ? `#${d.text}` : inkOn(d.color), ring: near ? `border-2 border-[${t.muted}]` : '' }
}

// ---------------------------------------------------------------- drawing

// Sizes are for a panel about 480 px on its shorter side; a big one (the
// 13.3" e-paper, 1200 px) draws them K times larger, by halves.
let K = 1
const px = (n: number) => Math.round(n * K)

type Sizes = { small: boolean; name: number; clock: number; dest: number; badge: number; badgeH: number; time: number; unit: number; foot: number; row: number; pad: number; gap: number; timeW: number; where: boolean }

function sizesFor(small: boolean, narrow: boolean): Sizes {
  if (small) return { small, name: 20, clock: 20, dest: 16, badge: 14, badgeH: 24, time: 18, unit: 12, foot: 11, row: 36, pad: 10, gap: 8, timeW: 62, where: false }
  return { small, name: 30, clock: 30, dest: narrow ? 21 : 24, badge: narrow ? 18 : 20, badgeH: narrow ? 32 : 36, time: narrow ? 24 : 28, unit: narrow ? 14 : 16, foot: 15, row: narrow ? 48 : 54, pad: 20, gap: 12, timeW: narrow ? 92 : 108, where: !narrow }
}

const LiveMark = ({ color, size }: { color: string; size: number }) => (
  <svg className={`w-[${size}px] h-[${size}px]`} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={2.6} strokeLinecap="round">
    <circle cx="12" cy="17" r="2.2" fill={color} stroke="none" />
    <path d="M7.5 12.5a6.4 6.4 0 0 1 9 0" />
    <path d="M4 9a11.3 11.3 0 0 1 16 0" />
  </svg>
)

const ClockMark = ({ color, size }: { color: string; size: number }) => (
  <svg className={`w-[${size}px] h-[${size}px]`} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round">
    <circle cx="12" cy="12" r="8.5" />
    <path d="M12 7.5V12l3 2" />
  </svg>
)

function Row({ d, t, z, now, twelve, badgeW, rowH, last }: { d: Departure; t: Theme; z: Sizes; now: number; twelve: boolean; badgeW: number; rowH: number; last: boolean }) {
  const badge = badgeOf(t, d)
  const when = whenText(d.at, now, twelve)
  const late = delayText(d.delay)
  // Too narrow for a chip (a 2.8" screen): the time itself in the delay's color.
  const chip = late && !d.gone && !z.small
  const timeColor = d.gone ? t.gone : late && z.small && !t.high ? (late[0] === '+' ? t.late : t.early) : d.live ? t.ink : t.muted
  const rule = last ? '' : t.high ? 'border-b-2 border-black' : `border-b border-[${t.rule}]`
  return (
    <div className={`flex items-center gap-[${px(z.gap)}px] h-[${rowH}px] ${rule}`}>
      <div className={`shrink-0 flex items-center justify-center w-[${badgeW}px] h-[${px(z.badgeH)}px] rounded-[${px(z.badgeH / 4)}px] bg-[${badge.back}] ${badge.ring} text-[${badge.ink}] text-[${px(z.badge)}px] font-bold`}>
        <span className="truncate">{d.line || '?'}</span>
      </div>
      <span className={`flex-1 min-w-0 truncate text-[${px(z.dest)}px] ${d.gone ? `text-[${t.muted}]` : ''}`}>{d.to || d.line}</span>
      {z.where && d.where ? <span className={`shrink-0 text-[${px(z.unit)}px] text-[${t.muted}]`}>{d.where}</span> : null}
      {chip ? (
        <span className={`shrink-0 px-[${px(6)}px] rounded-[${px(6)}px] text-[${px(z.unit)}px] font-bold ${late[0] === '+' ? t.chipLate : t.chipEarly}`}>{late}</span>
      ) : null}
      <div className={`shrink-0 w-[${px(z.timeW)}px] flex items-center justify-end gap-[${px(4)}px] text-[${timeColor}]`}>
        {d.gone ? (
          <span className={`text-[${px(z.unit + 2)}px] font-bold`}>Canceled</span>
        ) : (
          <>
            {d.live ? <LiveMark color={t.live} size={px(z.unit)} /> : <ClockMark color={t.muted} size={px(z.unit)} />}
            <span className={`${when.unit || when.big === 'Now' ? `text-[${px(z.time)}px]` : `text-[${px(z.time - 4)}px]`} ${d.live ? 'font-bold' : ''}`}>{when.big}</span>
            {when.unit ? <span className={`text-[${px(z.unit)}px]`}>{when.unit}</span> : null}
          </>
        )}
      </div>
    </div>
  )
}

// One stop: its name (and the clock beside the first), and as many rows as
// fit in `height`, sharing what is left over.
function Section({ stop, list, t, z, now, twelve, clock, height, width, center = false }: { stop: Stop; list: Departure[]; t: Theme; z: Sizes; now: number; twelve: boolean; clock: string; height: number; width: number; center?: boolean }) {
  const headH = px(z.name * 1.5)
  const rows = Math.max(1, Math.floor((height - headH) / px(z.row)))
  const rowH = Math.min(Math.floor((height - headH) / rows), px(z.row * 1.25))
  const shown = list.slice(0, rows)
  // Every badge of the section as wide as its longest name needs, within reason.
  const longest = shown.reduce((n, d) => Math.max(n, String(d.line || '?').length), 1)
  const badgeW = Math.min(Math.round(width * 0.24), px(z.badge * (0.66 * Math.min(longest, 6) + 1.2)))
  return (
    <div className={`flex flex-col w-[${width}px] h-[${height}px]`}>
      <div className={`flex items-center ${center ? 'justify-center' : ''} h-[${headH}px] gap-[${px(z.gap)}px]`}>
        <span className={`${center ? 'text-center' : 'flex-1'} min-w-0 truncate text-[${px(z.name)}px] font-bold`}>{stop.name}</span>
        {clock ? <span className={`shrink-0 text-[${px(z.clock)}px] text-[${t.muted}]`}>{clock}</span> : null}
      </div>
      {shown.length ? (
        shown.map((d, i) => <Row d={d} t={t} z={z} now={now} twelve={twelve} badgeW={badgeW} rowH={rowH} last={i === shown.length - 1} />)
      ) : (
        <span className={`text-[${px(z.dest)}px] text-[${t.muted}] pt-[${px(z.gap)}px]`}>No departures coming up</span>
      )}
    </div>
  )
}

// The line at the bottom: what the marks mean and how fresh it is, or what
// went wrong. A tap on it asks again.
function Footer({ board, t, z, now, twelve, loading, provider, width, compact, center = false }: { board: Board | null; t: Theme; z: Sizes; now: number; twelve: boolean; loading: boolean; provider: string; width: number; compact: boolean; center?: boolean }) {
  const ask = () => frameos.remember('force', true)
  const h = px(z.foot * 1.8)
  if (board?.error) {
    const kept = board.at > 0 ? (compact ? ` (from ${clockText(board.at, twelve)})` : ` Showing departures from ${clockText(board.at, twelve)}.`) : ''
    return (
      <div className={`flex items-center w-[${width}px] min-h-[${h}px] px-[${px(8)}px] rounded-[${px(6)}px] ${t.barError} text-[${px(z.foot)}px]`} onClick={ask}>
        <span className="line-clamp-2">{`${provider}: ${board.error}.${kept}`}</span>
      </div>
    )
  }
  const fresh = loading ? 'Updating…' : board?.at ? `Updated ${agoText(board.at, now, twelve)}` : ''
  const feedOld = board?.feedTime && now - board.feedTime > 10 * MINUTE ? ` · feed ${agoText(board.feedTime, now, twelve)}` : ''
  return (
    <div className={`flex items-center w-[${width}px] h-[${h}px] gap-[${px(6)}px] text-[${px(z.foot)}px] ${t.bar}`} onClick={ask}>
      {compact ? null : <LiveMark color={t.live} size={px(z.foot)} />}
      {compact ? null : <span className={`pr-[${px(8)}px]`}>Live</span>}
      {compact ? null : <ClockMark color={t.muted} size={px(z.foot)} />}
      {compact ? null : <span>Timetable</span>}
      {/* A spring and the words: a truncated text-right span drew nothing on 2026.11.14. */}
      <div className={center ? '' : 'flex-1'} />
      <span className={`min-w-0 truncate ${center ? 'flex-1 text-center' : ''}`}>{`${fresh}${feedOld}`}</span>
    </div>
  )
}

function Setup({ t, text, W, H, round }: { t: Theme; text: string; W: number; H: number; round: boolean }) {
  const side = round ? Math.floor((Math.min(W, H) / 2 - 12) * Math.SQRT2) : W
  return (
    <div className={`flex items-center justify-center w-[${W}px] h-[${H}px] bg-[${t.page}] text-[${t.ink}]`}>
      <div className={`flex flex-col items-center gap-[${px(12)}px] w-[${side}px] p-[${px(24)}px] text-center`}>
        <span className={`text-[${px(28)}px] font-bold`}>Transit departures</span>
        <span className={`text-[${px(18)}px] text-[${t.muted}]`}>{text}</span>
      </div>
    </div>
  )
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const round = context?.round === true
  const t = themeOf(app)
  const twelve = app.state.clock === '12'
  const c = configOf(app)
  const now = Date.now()
  K = !round && Math.min(W, H) >= 900 ? Math.min(3, Math.floor((Math.min(W, H) / 480) * 2) / 2) : 1

  const problem = setupProblem(c)
  if (problem) return <Setup t={t} text={problem} W={W} H={H} round={round} />

  const key = keyOf(c)
  let board: (Board & { loading?: boolean }) | null = loadBoard(app, key)
  const force = frameos.recall('force') === true
  if (force) frameos.remember('force', null)
  if (!board || force || now - (board.tried || 0) >= FETCH_GAP) board = refresh(app, c, board, now)
  const loading = board?.loading === true
  const provider = PROVIDERS[c.provider]

  // The departures still to catch: a list fetched a while ago counts down
  // from the clock and loses the ones gone.
  const stops: Stop[] = (board?.stops || []).map((s, i) => ({ name: c.labels[i] || s.name || c.stops[i] || '', list: upcoming(s.list || [], now, c.walk, c.only) }))
  const clock = clockText(now, twelve)

  if (!stops.length) {
    const text = board?.error ? `${provider}: ${board.error}.` : `Loading departures from ${provider}…`
    return <Setup t={t} text={text} W={W} H={H} round={round} />
  }

  if (round) {
    // One list in the circle: both stops' departures by time, the first
    // stop's name and the clock in the arc above, the freshness below.
    const R = Math.min(W, H) / 2 - 12
    const z = sizesFor(R < 200, true)
    const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))
    const top = Math.round(R * 0.62)
    const bottom = Math.round(R * 0.6)
    const listW = Math.min(chord(top), chord(bottom))
    const merged: Stop = { name: stops.map((s) => s.name).join(' · '), list: stops.flatMap((s) => s.list).sort((a, b) => a.at - b.at) }
    const footW = chord(R * 0.78)
    return (
      <div className={`relative w-[${W}px] h-[${H}px] bg-[${t.page}] text-[${t.ink}]`}>
        <div className={`absolute left-[${Math.round(W / 2 - chord(R * 0.86) / 2)}px] top-[${Math.round(H / 2 - R * 0.86)}px] w-[${chord(R * 0.86)}px] flex flex-col items-center`}>
          <span className={`text-[${px(z.clock)}px] text-[${t.muted}]`}>{clock}</span>
        </div>
        <div className={`absolute left-[${Math.round(W / 2 - listW / 2)}px] top-[${Math.round(H / 2 - top)}px]`}>
          <Section stop={merged} list={merged.list} t={t} z={z} now={now} twelve={twelve} clock="" height={top + bottom} width={listW} center />
        </div>
        <div className={`absolute left-[${Math.round(W / 2 - footW / 2)}px] top-[${Math.round(H / 2 + R * 0.66)}px]`}>
          <Footer board={board} t={t} z={z} now={now} twelve={twelve} loading={loading} provider={provider} width={footW} compact center />
        </div>
      </div>
    )
  }

  const small = Math.min(W, H) < 330
  const wide = W >= H * 1.3 && W >= 640
  const columns = stops.length > 1 && wide
  const z0 = sizesFor(small, columns || W < 520)
  const pad = px(z0.pad)
  const gap = px(z0.gap * 2)
  const footH = px(z0.foot * 1.8) + (board?.error ? px(z0.foot * 1.3) : 0)
  const innerW = W - pad * 2
  const bodyH = H - pad * 2 - footH - px(z0.gap)
  const colW = columns ? Math.floor((innerW - gap) / 2) : innerW
  const sections = columns
    ? stops.map((s, i) => ({ s, h: bodyH, clock: i === stops.length - 1 ? clock : '' }))
    : stops.map((s, i) => ({ s, h: stops.length > 1 ? Math.floor((bodyH - gap) / 2) : bodyH, clock: i === 0 ? clock : '' }))
  return (
    <div className={`flex flex-col w-[${W}px] h-[${H}px] p-[${pad}px] gap-[${px(z0.gap)}px] bg-[${t.page}] text-[${t.ink}]`}>
      <div className={`flex ${columns ? 'flex-row' : 'flex-col'} gap-[${gap}px] h-[${bodyH}px]`}>
        {sections.map(({ s, h, clock: shownClock }) => (
          <Section stop={s} list={s.list} t={t} z={z0} now={now} twelve={twelve} clock={shownClock} height={h} width={colW} />
        ))}
      </div>
      <Footer board={board} t={t} z={z0} now={now} twelve={twelve} loading={loading} provider={provider} width={innerW} compact={small} />
    </div>
  )
}

sources.board.ts:
// What a station board shows of the departures it has: which ones, the time
// as minutes or a clock, a delay, and a line's color as each panel can show
// it.
import type { Departure } from './gtfsrt'

export type Stop = { name: string; list: Departure[] }

// The last good departures, kept in the scene's private `board` field (on
// disk), and what happened since: `at` when they came, `tried` when the last
// request went out, `error` what went wrong with it.
export type Board = {
  key: string
  at: number
  tried: number
  stops: Stop[]
  error: string
  feedTime?: number
  names?: Record<string, { id: string; name: string }>
}

export const MINUTE = 60 * 1000

// The departures still to come that a person at this stop can catch, of the
// lines asked for.
export function upcoming(list: Departure[], now: number, walkMinutes: number, only: string[]): Departure[] {
  const from = now + Math.max(0, walkMinutes) * MINUTE - 30 * 1000
  const wanted = only.map((name) => name.toLowerCase())
  return list.filter((d) => d.at >= from && (!wanted.length || wanted.indexOf(String(d.line).toLowerCase()) >= 0))
}

export function clockText(at: number, twelve: boolean): string {
  const d = new Date(at)
  const minutes = String(d.getMinutes()).padStart(2, '0')
  if (!twelve) return `${d.getHours()}:${minutes}`
  const hour = d.getHours() % 12 || 12
  return `${hour}:${minutes} ${d.getHours() < 12 ? 'am' : 'pm'}`
}

// "Now", "4 min", or past the hour the clock time: { big, unit }.
export function whenText(at: number, now: number, twelve: boolean): { big: string; unit: string } {
  const minutes = Math.floor((at - now) / MINUTE)
  if (minutes <= 0) return { big: 'Now', unit: '' }
  if (minutes < 60) return { big: String(minutes), unit: 'min' }
  return { big: clockText(at, twelve), unit: '' }
}

// A delay worth saying, in whole minutes: "+3", "-1", or "".
export function delayText(delay: number | null): string {
  if (delay === null || delay === undefined || !isFinite(delay)) return ''
  const minutes = Math.round(delay / 60)
  if (minutes >= 1) return `+${minutes}`
  if (minutes <= -1) return `${minutes}`
  return ''
}

// How long ago, said plainly: "just now", "4 min ago", "at 10:20".
export function agoText(at: number, now: number, twelve: boolean): string {
  const minutes = Math.floor((now - at) / MINUTE)
  if (minutes < 1) return 'just now'
  if (minutes < 60) return `${minutes} min ago`
  return `at ${clockText(at, twelve)}`
}

// A color's parts, from "DA291C" or "#da291c".
function rgb(hex: string): [number, number, number] {
  const h = String(hex || '').replace('#', '')
  return [parseInt(h.slice(0, 2), 16) || 0, parseInt(h.slice(2, 4), 16) || 0, parseInt(h.slice(4, 6), 16) || 0]
}

// How light a color looks, 0 to 255.
export function lightness(hex: string): number {
  const [r, g, b] = rgb(hex)
  return 0.299 * r + 0.587 * g + 0.114 * b
}

// Black or white, whichever reads on this color.
export function inkOn(hex: string): string {
  return lightness(hex) > 150 ? '#000000' : '#ffffff'
}

// Color e-paper (Spectra's six inks, as dither.nim measures them): a line's
// color as the nearest ink, so a badge is one solid ink and not a dither.
export const INKS = { red: '#6b1119', yellow: '#c7bb00', green: '#2a5531', blue: '#18539a', black: '#000000' }

export function nearestInk(hex: string): string {
  const [r, g, b] = rgb(hex)
  const max = Math.max(r, g, b)
  const min = Math.min(r, g, b)
  if (max - min < 48) return INKS.black
  let hue = 0
  if (max === r) hue = ((g - b) / (max - min)) * 60
  else if (max === g) hue = (2 + (b - r) / (max - min)) * 60
  else hue = (4 + (r - g) / (max - min)) * 60
  if (hue < 0) hue += 360
  if (hue < 15 || hue >= 300) return INKS.red
  if (hue < 70) return INKS.yellow
  if (hue < 170) return INKS.green
  return INKS.blue
}

// "Red, 47" as a list of names.
export function namesOf(text: string): string[] {
  return String(text || '')
    .split(',')
    .map((part) => part.trim())
    .filter(Boolean)
}

sources.providers.ts:
// The agencies' own departure APIs, each read into the same rows. All three
// answer small JSON (10 to 50 KB for a stop) and need no key, so they work
// the same on a Raspberry Pi and an ESP32.
import type { Departure } from './gtfsrt'

export type StopBoard = { name: string; list: Departure[] }

// A request that answers JSON, or throws with what went wrong.
function getJson(url: string, options: Record<string, any> = {}): any {
  const reply = frameos.httpRequest(url, { timeoutMs: 20000, ...options })
  if (!reply || reply.error) throw new Error(reply?.error || 'no answer')
  if (reply.status === 429) throw new Error('too many requests (HTTP 429): try a longer refresh interval')
  if (reply.status < 200 || reply.status >= 300) throw new Error(`HTTP ${reply.status}`)
  try {
    return JSON.parse(reply.body || 'null')
  } catch (e) {
    throw new Error('the answer was not JSON')
  }
}

const enc = encodeURIComponent
const when = (text: any): number => (text ? Date.parse(String(text)) : NaN)
const hex = (text: any): string => (/^#?[0-9a-fA-F]{6}$/.test(String(text || '')) ? String(text).replace('#', '').toUpperCase() : '')

function row(line: string, color: string, text: string, to: string, at: number, live: boolean, delay: number | null, gone: boolean, where: string): Departure {
  return { line, color, text, to, at, live, delay, gone, where }
}

// ---------------------------------------------------------------- MBTA
// api-v3.mbta.com: predictions (realtime) and schedules for one stop or
// station, a few ids with commas ("place-pktrm", "1123"). Without a key it
// allows 20 requests a minute, two a stop here.

// The hour and minute it is in Boston now, as MBTA's schedules count them.
function bostonTime(now: number): { hour: number; text: string } {
  let offset = -5 * 3600
  try {
    const zone = typeof frameos.timeZone === 'function' ? frameos.timeZone('America/New_York') : null
    const changes = zone?.changes || []
    for (let i = 0; i + 1 < changes.length; i += 2) {
      if (changes[i] * 1000 <= now) offset = changes[i + 1]
    }
    if (!changes.length) {
      // No zone data: daylight time from the second Sunday of March to the first of November.
      const d = new Date(now)
      const y = d.getUTCFullYear()
      const sunday = (month: number, nth: number) => {
        const first = new Date(Date.UTC(y, month, 1)).getUTCDay()
        return Date.UTC(y, month, 1 + ((7 - first) % 7) + (nth - 1) * 7, 7)
      }
      if (now >= sunday(2, 2) && now < sunday(10, 1)) offset = -4 * 3600
    }
  } catch (e) {
    // keep the standard offset
  }
  const local = new Date(now + offset * 1000)
  const hour = local.getUTCHours()
  return { hour, text: `${String(hour).padStart(2, '0')}:${String(local.getUTCMinutes()).padStart(2, '0')}` }
}

function mbtaLine(route: any): { label: string; color: string; text: string } {
  const a = route?.attributes || {}
  let label = String(a.short_name || '')
  if (a.type === 2) label = 'CR'
  else if (a.type === 4) label = 'Ferry'
  else if (!label) label = String(a.long_name || route?.id || '').replace(/ Line$/, '').replace(/ Trolley$/, '')
  return { label, color: hex(a.color), text: hex(a.text_color) }
}

export function mbta(stop: string, now: number): StopBoard {
  const ids = stop.split(',').map((s) => s.trim()).filter(Boolean).join(',')
  const base = 'https://api-v3.mbta.com'
  const shared = `&fields%5Btrip%5D=headsign&fields%5Broute%5D=color,text_color,short_name,long_name,type&fields%5Bstop%5D=name,platform_code`
  // Sorted by departure, the trains that end here (no departure) come first:
  // 60 leaves room for a terminal's (South Station's are half of them).
  const predictions = getJson(
    `${base}/predictions?filter%5Bstop%5D=${enc(ids)}&sort=departure_time&page%5Blimit%5D=60&include=trip,route,stop,schedule${shared}` +
      `&fields%5Bprediction%5D=departure_time,schedule_relationship&fields%5Bschedule%5D=departure_time`,
  )
  const included: Record<string, any> = {}
  const keep = (doc: any) => {
    for (const item of doc?.included || []) included[`${item.type}/${item.id}`] = item
  }
  keep(predictions)
  const rel = (item: any, name: string) => {
    const data = item?.relationships?.[name]?.data
    return data ? included[`${data.type}/${data.id}`] : null
  }
  const list: Departure[] = []
  const trips: Record<string, boolean> = {}
  // The last live departure of each line and destination: the timetable
  // says nothing new before it (the subway's timetable is only a pattern).
  const liveUntil: Record<string, number> = {}
  let name = ''
  const where = (item: any, route: any) => {
    const s = rel(item, 'stop')
    if (!name && s?.attributes?.name) name = s.attributes.name
    const code = s?.attributes?.platform_code
    return route?.attributes?.type === 2 && code ? `Track ${code}` : ''
  }
  for (const p of predictions?.data || []) {
    const a = p.attributes || {}
    const route = rel(p, 'route')
    const trip = rel(p, 'trip')
    const schedule = rel(p, 'schedule')
    const planned = when(schedule?.attributes?.departure_time)
    const gone = a.schedule_relationship === 'CANCELLED' || a.schedule_relationship === 'SKIPPED'
    // No departure time: the trip ends here, or it does not stop.
    const at = gone ? planned : when(a.departure_time)
    if (!(at > 0)) continue
    const line = mbtaLine(route)
    const delay = !gone && planned > 0 ? Math.round((at - planned) / 1000) : null
    const to = trip?.attributes?.headsign || ''
    list.push(row(line.label, line.color, line.text, to, at, !gone, delay, gone, where(p, route)))
    if (p.relationships?.trip?.data?.id) trips[p.relationships.trip.data.id] = true
    if (!gone) liveUntil[`${line.label}|${to}`] = Math.max(liveUntil[`${line.label}|${to}`] || 0, at)
  }
  // The timetable for what has no prediction yet (a bus later today), by
  // Boston's clock; after midnight the service day is yesterday's, and the
  // predictions alone are shown.
  // Asked only when the predictions do not fill a board: a station's do, and
  // the stop costs one request (20 a minute without a key).
  const boston = bostonTime(now)
  if (boston.hour >= 3 && list.filter((d) => !d.gone).length < 10) {
    const schedules = getJson(
      `${base}/schedules?filter%5Bstop%5D=${enc(ids)}&filter%5Bmin_time%5D=${boston.text}&sort=departure_time&page%5Blimit%5D=20&include=trip,route,stop${shared}` +
        `&fields%5Bschedule%5D=departure_time`,
    )
    keep(schedules)
    for (const s of schedules?.data || []) {
      const tripId = s.relationships?.trip?.data?.id
      if (tripId && trips[tripId]) continue
      const at = when(s.attributes?.departure_time)
      if (!(at > 0)) continue
      const route = rel(s, 'route')
      const line = mbtaLine(route)
      const to = rel(s, 'trip')?.attributes?.headsign || ''
      if (at <= (liveUntil[`${line.label}|${to}`] || 0)) continue
      list.push(row(line.label, line.color, line.text, to, at, false, null, false, where(s, route)))
    }
  }
  if (!name) {
    // Nothing coming: the stop's own name.
    const first = ids.split(',')[0]
    try {
      name = getJson(`${base}/stops/${enc(first)}?fields%5Bstop%5D=name`)?.data?.attributes?.name || first
    } catch (e) {
      if (String((e as any)?.message).indexOf('HTTP 404') >= 0) throw new Error(`no stop with the id ${first}`)
      name = first
    }
  }
  list.sort((x, y) => x.at - y.at)
  return { name, list }
}

// ---------------------------------------------------------------- Entur
// api.entur.io: every operator in Norway, a stop place or a quay by its id
// (NSR:StopPlace:58366) or by its name, looked up once. Entur asks every
// client to say who it is in ET-Client-Name.
const ENTUR_HEADERS = { 'ET-Client-Name': 'frameos-transitdepartures', 'Content-Type': 'application/json' }

export function enturStopId(stop: string): { id: string; name: string } {
  const text = stop.trim()
  if (/^NSR:(StopPlace|Quay):\d+$/.test(text)) return { id: text, name: '' }
  const found = getJson(`https://api.entur.io/geocoder/v1/autocomplete?text=${enc(text)}&layers=venue&size=1&lang=en`, {
    headers: { 'ET-Client-Name': ENTUR_HEADERS['ET-Client-Name'] },
  })
  const place = found?.features?.[0]?.properties
  if (!place?.id) throw new Error(`no stop called "${text}"`)
  return { id: place.id, name: place.name || place.label || text }
}

const ENTUR_MODES: Record<string, string> = { metro: 'EC700C', tram: '0B91EF', rail: '2C3E50', bus: 'E60000', water: '0073A8', coach: '6E3F8C' }

export function entur(id: string, now: number): StopBoard {
  const quay = id.indexOf(':Quay:') > 0
  const calls =
    'estimatedCalls(numberOfDepartures: 24, timeRange: 72000, includeCancelledTrips: true) { realtime cancellation aimedDepartureTime expectedDepartureTime ' +
    'destinationDisplay { frontText } quay { publicCode } serviceJourney { line { publicCode name transportMode presentation { colour textColour } } } }'
  const query = `{ place: ${quay ? 'quay' : 'stopPlace'}(id: ${JSON.stringify(id)}) { name ${calls} } }`
  const doc = getJson('https://api.entur.io/journey-planner/v3/graphql', {
    method: 'POST',
    headers: ENTUR_HEADERS,
    body: JSON.stringify({ query }),
  })
  if (doc?.errors?.length) throw new Error(String(doc.errors[0]?.message || 'Entur refused the query'))
  const place = doc?.data?.place
  if (!place) throw new Error(`no stop with the id ${id}`)
  const list: Departure[] = []
  for (const call of place.estimatedCalls || []) {
    const line = call.serviceJourney?.line || {}
    const mode = String(line.transportMode || '')
    const aimed = when(call.aimedDepartureTime)
    const expected = when(call.expectedDepartureTime)
    const at = expected > 0 ? expected : aimed
    if (!(at > 0)) continue
    const code = call.quay?.publicCode ? String(call.quay.publicCode) : ''
    const label = String(line.publicCode || line.name || '').slice(0, 12)
    list.push(
      row(
        label,
        hex(line.presentation?.colour) || ENTUR_MODES[mode] || '',
        hex(line.presentation?.textColour),
        call.destinationDisplay?.frontText || '',
        at,
        call.realtime === true,
        call.realtime === true && aimed > 0 ? Math.round((expected - aimed) / 1000) : null,
        call.cancellation === true,
        code && !quay ? `${mode === 'rail' || mode === 'metro' ? 'Platform' : 'Stop'} ${code}` : '',
      ),
    )
  }
  list.sort((x, y) => x.at - y.at)
  return { name: place.name || id, list }
}

// ---------------------------------------------------------------- TfL
// api.tfl.gov.uk: the arrivals at one stop point, by its id (940GZZLUKSX
// for King's Cross St. Pancras on the Underground, 490000129R for a bus
// stop). Every arrival is a prediction; TfL publishes no timetable here.
const TFL_LINES: Record<string, [string, string, string]> = {
  bakerloo: ['BAK', 'B36305', 'FFFFFF'],
  central: ['CEN', 'E32017', 'FFFFFF'],
  circle: ['CIR', 'FFD300', '00205B'],
  district: ['DIS', '00782A', 'FFFFFF'],
  'hammersmith-city': ['H&C', 'F3A9BB', '00205B'],
  jubilee: ['JUB', 'A0A5A9', 'FFFFFF'],
  metropolitan: ['MET', '9B0056', 'FFFFFF'],
  northern: ['NOR', '000000', 'FFFFFF'],
  piccadilly: ['PIC', '003688', 'FFFFFF'],
  victoria: ['VIC', '0098D4', 'FFFFFF'],
  'waterloo-city': ['W&C', '95CDBA', '00205B'],
  elizabeth: ['ELZ', '6950A1', 'FFFFFF'],
  dlr: ['DLR', '00A4A7', 'FFFFFF'],
  liberty: ['LIB', '5D6061', 'FFFFFF'],
  lioness: ['LIO', 'FAA61A', '00205B'],
  mildmay: ['MIL', '0077AD', 'FFFFFF'],
  suffragette: ['SUF', '5BBD72', 'FFFFFF'],
  weaver: ['WEA', '823A62', 'FFFFFF'],
  windrush: ['WIN', 'ED1B00', 'FFFFFF'],
}

const tflPlace = (text: any) =>
  String(text || '')
    .replace(/ (Underground|DLR|Rail|Overground|Elizabeth Line) Station$/i, '')
    .replace(/ Station$/i, '')
    .replace(/ \(London\)$/i, '')
    .trim()

export function tfl(stop: string, now: number): StopBoard {
  const id = stop.trim()
  const arrivals = getJson(`https://api.tfl.gov.uk/StopPoint/${enc(id)}/Arrivals`)
  if (!Array.isArray(arrivals)) throw new Error('TfL did not answer with arrivals')
  let name = ''
  const list: Departure[] = []
  for (const a of arrivals) {
    const at = when(a.expectedArrival)
    if (!(at > 0)) continue
    if (!name && a.stationName) name = tflPlace(a.stationName)
    const known = TFL_LINES[String(a.lineId || '')]
    const bus = a.modeName === 'bus'
    const platform = String(a.platformName || '')
    const where = /unknown|null/i.test(platform) || !platform ? '' : bus ? `Stop ${platform}` : platform.split(' - ').pop() || ''
    list.push(
      row(
        known ? known[0] : String(a.lineName || ''),
        known ? known[1] : bus ? 'E1251B' : '',
        known ? known[2] : 'FFFFFF',
        tflPlace(a.destinationName) || String(a.towards || ''),
        at,
        true,
        null,
        false,
        where,
      ),
    )
  }
  list.sort((x, y) => x.at - y.at)
  return { name: name || id, list: list.slice(0, 30) }
}

sources.gtfsrt.ts:
// GTFS-Realtime TripUpdates, read as the feed streams in.
//
// A feed is one protobuf FeedMessage for a whole network: 0.6 to 1.1 MB for a
// city (MBTA, SEPTA, Helsinki, Halifax), 4 to 15 MB for a country. A frame
// never holds it: the body comes in pieces (fetch's onChunk), each piece is
// walked entity by entity and dropped, and only the departures at the stops
// asked for are kept. An entity is decoded only when one of those stop ids
// is in it, which a native indexOf finds; the others are stepped over by
// their length. So the work is a few reads per entity, not per byte.
//
// The pieces are text. The runtime reads a body that is not UTF-8 as
// Windows-1252, one character a byte, from its first piece on (protobuf is
// never UTF-8 for long), so every byte comes back: below 256 a character is
// its byte, and the 27 characters Windows-1252 puts at 0x80 to 0x9f are
// turned back here (BACK). A body read whole with httpRequest's base64 is
// one character a byte already.
//
// The fields read (gtfs-realtime.proto):
//   FeedMessage   1 header, 2 entity
//   FeedHeader    3 timestamp
//   FeedEntity    2 is_deleted, 3 trip_update
//   TripUpdate    1 trip, 2 stop_time_update, 5 delay, 6 trip_properties
//   TripDescriptor 4 schedule_relationship, 5 route_id, 6 direction_id
//   TripProperties 5 trip_headsign
//   StopTimeUpdate 2 arrival, 3 departure, 4 stop_id, 5 schedule_relationship
//   StopTimeEvent  1 delay, 2 time, 4 scheduled_time

export type Departure = {
  line: string
  color: string
  text: string
  to: string
  at: number
  live: boolean
  delay: number | null
  gone: boolean
  where: string
}

export type LineInfo = { label: string; color: string; to: string[] }

// Windows-1252's characters for bytes 0x80 to 0x9f, back to the bytes.
const BACK: Record<number, number> = {
  0x20ac: 0x80, 0x201a: 0x82, 0x0192: 0x83, 0x201e: 0x84, 0x2026: 0x85, 0x2020: 0x86, 0x2021: 0x87,
  0x02c6: 0x88, 0x2030: 0x89, 0x0160: 0x8a, 0x2039: 0x8b, 0x0152: 0x8c, 0x017d: 0x8e,
  0x2018: 0x91, 0x2019: 0x92, 0x201c: 0x93, 0x201d: 0x94, 0x2022: 0x95, 0x2013: 0x96, 0x2014: 0x97,
  0x02dc: 0x98, 0x2122: 0x99, 0x0161: 0x9a, 0x203a: 0x9b, 0x0153: 0x9c, 0x017e: 0x9e, 0x0178: 0x9f,
}

// A character no Windows-1252 byte becomes: the piece was read as UTF-8.
const NOT_1252 = /[^\x00-\xff\u0152\u0153\u0160\u0161\u0178\u017d\u017e\u0192\u02c6\u02dc\u2013\u2014\u2018-\u201a\u201c-\u201e\u2020-\u2022\u2026\u2030\u2039\u203a\u20ac\u2122]/

// A piece the runtime read as UTF-8 (a first piece that happened to be
// valid UTF-8): its bytes again, one character each.
function utf8Bytes(text: string): string {
  const bytes = new TextEncoder().encode(text)
  let out = ''
  for (let i = 0; i < bytes.length; i += 4096) {
    out += String.fromCharCode.apply(null, Array.from(bytes.subarray(i, i + 4096)))
  }
  return out
}

// Bytes of the feed as text: a route id or a headsign, which may be UTF-8.
function text(from: number, to: number): string {
  const raw = S.slice(from, to)
  if (!/[^\x00-\x7f]/.test(raw)) return raw
  const bytes = new Uint8Array(raw.length)
  for (let i = 0; i < raw.length; i++) {
    const c = raw.charCodeAt(i)
    bytes[i] = c < 256 ? c : BACK[c] ?? 0x3f
  }
  return new TextDecoder().decode(bytes)
}

// A stop id as the feed's bytes, to be found in them.
function idBytes(id: string): string {
  return /[^\x00-\x7f]/.test(id) ? utf8Bytes(id) : id
}

// The reader: S the bytes, P where it is, E where it must stop.
let S = ''
let P = 0
let E = 0

function byte(): number {
  const c = S.charCodeAt(P++)
  return c < 256 ? c : BACK[c] ?? 0
}

// A varint as a number (exact to 2^53: times, lengths, ids). Past E, P is
// left past E, which is how a caller learns the piece ended inside it.
function varint(): number {
  let value = 0
  let scale = 1
  for (;;) {
    if (P >= E) {
      P = E + 1
      return 0
    }
    const c = byte()
    value += (c & 127) * scale
    if (c < 128) return value
    scale *= 128
  }
}

// An int32 varint (a delay): its low 32 bits, signed. A negative one is ten
// bytes long.
function int32(): number {
  let low = 0
  let shift = 0
  for (;;) {
    if (P >= E) return low | 0
    const c = byte()
    if (shift < 32) low |= (c & 127) << shift
    shift += 7
    if (c < 128) return low | 0
  }
}

// Steps over a field of this wire type; false when the piece ends inside it.
function skip(wire: number): boolean {
  if (wire === 0) varint()
  else if (wire === 1) P += 8
  else if (wire === 2) {
    const n = varint()
    if (P <= E) P += n
  } else if (wire === 5) P += 4
  else throw new Error('not a GTFS-Realtime feed (an unknown field type)')
  return P <= E
}

type Event = { time: number; delay: number | null; scheduled: number }

function stopEvent(from: number, to: number): Event {
  const ev: Event = { time: 0, delay: null, scheduled: 0 }
  P = from
  E = to
  while (P < E) {
    const tag = varint()
    const field = tag >>> 3
    const wire = tag & 7
    if (field === 1 && wire === 0) ev.delay = int32()
    else if (field === 2 && wire === 0) ev.time = varint()
    else if (field === 4 && wire === 0) ev.scheduled = varint()
    else skip(wire)
  }
  return ev
}

export type Scan = {
  stops: { ids: string[]; list: Departure[] }[]
  lines: Record<string, LineInfo>
  now: number
  feedTime: number
  entities: number
  bytes: number
}

export function lineOf(lines: Record<string, LineInfo>, route: string): LineInfo {
  return lines[route] || { label: route, color: '', to: [] }
}

// One trip's update: the departures it makes from the stops asked for.
function tripUpdate(scan: Scan, from: number, to: number) {
  let route = ''
  let direction = -1
  let canceled = false
  let headsign = ''
  let tripDelay: number | null = null
  const updates: number[] = []
  P = from
  E = to
  while (P < E) {
    const tag = varint()
    const field = tag >>> 3
    const wire = tag & 7
    if (wire === 2 && (field === 1 || field === 2 || field === 6)) {
      const n = varint()
      const start = P
      P += n
      if (field === 2) updates.push(start, P)
      else {
        // The trip, or its properties: read them here and come back.
        const back = P
        P = start
        E = back
        while (P < E) {
          const t = varint()
          const f = t >>> 3
          const w = t & 7
          if (field === 1 && f === 5 && w === 2) {
            const len = varint()
            route = text(P, P + len)
            P += len
          } else if (field === 1 && f === 6 && w === 0) direction = varint()
          else if (field === 1 && f === 4 && w === 0) canceled = varint() === 3
          else if (field === 6 && f === 5 && w === 2) {
            const len = varint()
            headsign = text(P, P + len)
            P += len
          } else skip(w)
        }
        P = back
        E = to
      }
    } else if (field === 5 && wire === 0) tripDelay = int32()
    else skip(wire)
  }
  const line = lineOf(scan.lines, route)
  const toward = headsign || (direction >= 0 ? line.to[direction] || line.to[0] || '' : line.to[0] || '')
  const last = updates.length - 2
  for (let u = 0; u < updates.length; u += 2) {
    // The stop's id first: most updates are of other stops.
    P = updates[u]
    E = updates[u + 1]
    let stop = ''
    let arrival = -1
    let departure = -1
    let skipped = false
    while (P < E) {
      const tag = varint()
      const field = tag >>> 3
      const wire = tag & 7
      if (wire === 2 && (field === 2 || field === 3 || field === 4)) {
        // An event is kept as where its length starts, and read only for a stop asked for.
        const lengthAt = P
        const n = varint()
        if (field === 4) stop = S.slice(P, P + n)
        else if (field === 2) arrival = lengthAt
        else departure = lengthAt
        P += n
      } else if (field === 5 && wire === 0) skipped = varint() === 1
      else skip(wire)
    }
    if (!stop) continue
    for (const board of scan.stops) {
      if (board.ids.indexOf(stop) < 0) continue
      // A trip that ends here makes no departure from here.
      if (u === last && departure < 0 && updates.length > 2) continue
      const at = departure >= 0 ? departure : arrival
      if (at < 0) continue
      P = at
      E = updates[u + 1]
      const n = varint()
      const ev = stopEvent(P, P + n)
      if (!ev.time) continue
      let delay = ev.scheduled ? ev.time - ev.scheduled : ev.delay
      if (delay === null) delay = tripDelay
      if (ev.time * 1000 < scan.now - 30000) continue
      board.list.push({
        line: line.label,
        color: line.color,
        text: '',
        to: toward,
        at: ev.time * 1000,
        live: true,
        delay,
        gone: canceled || skipped,
        where: '',
      })
    }
  }
}

function entity(scan: Scan, from: number, to: number) {
  let update = -1
  let updateEnd = -1
  let deleted = false
  P = from
  E = to
  while (P < E) {
    const tag = varint()
    const field = tag >>> 3
    const wire = tag & 7
    if (field === 3 && wire === 2) {
      const n = varint()
      update = P
      updateEnd = P + n
      P += n
    } else if (field === 2 && wire === 0) deleted = varint() !== 0
    else skip(wire)
  }
  if (update >= 0 && !deleted) tripUpdate(scan, update, updateEnd)
}

function header(scan: Scan, from: number, to: number) {
  P = from
  E = to
  while (P < E) {
    const tag = varint()
    if (tag >>> 3 === 3 && (tag & 7) === 0) scan.feedTime = varint()
    else skip(tag & 7)
  }
}

// The feed, a piece at a time: push() each piece, then end().
export class FeedScanner {
  scan: Scan
  rest = ''
  started = false
  needles: string[] = []

  constructor(stops: string[][], lines: Record<string, LineInfo>, now: number) {
    // The ids as the feed's bytes, the way a stop_id is compared.
    const byteIds = stops.map((ids) => ids.filter(Boolean).map(idBytes))
    this.scan = { stops: byteIds.map((ids) => ({ ids, list: [] })), lines, now, feedTime: 0, entities: 0, bytes: 0 }
    // A stop id in a StopTimeUpdate is field 4, length-delimited: the tag
    // byte 0x22 ('"'), its length, then its bytes.
    for (const ids of byteIds) {
      for (const id of ids) {
        if (id.length < 128) this.needles.push('"' + String.fromCharCode(id.length) + id)
      }
    }
  }

  nextMatch(from: number): number {
    let best = -1
    for (const needle of this.needles) {
      const at = S.indexOf(needle, from)
      if (at >= 0 && (best < 0 || at < best)) best = at
    }
    return best
  }

  // A piece of text as fetch's onChunk hands it over (binary: true for one
  // that is one character a byte already).
  push(piece: string, binary = false) {
    if (!piece) return
    const bytes = binary || !NOT_1252.test(piece) ? piece : utf8Bytes(piece)
    this.scan.bytes += bytes.length
    S = this.rest ? this.rest + bytes : bytes
    this.rest = ''
    P = 0
    E = S.length
    if (!this.started) {
      // A FeedMessage starts with its header, field 1. Anything else is
      // a page, an error in JSON or another format.
      const first = S.charCodeAt(0)
      if (first !== 0x0a) {
        const said = S.slice(0, 120).replace(/\s+/g, ' ').trim()
        throw new Error(first === 0x3c || first === 0x7b ? `not a GTFS-Realtime feed: "${said.slice(0, 80)}"` : 'not a GTFS-Realtime feed')
      }
      this.started = true
    }
    let next = this.nextMatch(0)
    for (;;) {
      if (P >= S.length) break
      const start = P
      E = S.length
      const tag = varint()
      if (P > E) {
        P = start
        break
      }
      const field = tag >>> 3
      const wire = tag & 7
      if (wire !== 2) {
        if (!skip(wire)) {
          P = start
          break
        }
        continue
      }
      const n = varint()
      if (P > E || P + n > E) {
        // The piece ends inside this one: it is read with the next.
        P = start
        break
      }
      const body = P
      const end = P + n
      if (field === 2) {
        this.scan.entities++
        if (next >= 0 && next < end) {
          entity(this.scan, body, end)
          next = this.nextMatch(end)
        }
      } else if (field === 1) header(this.scan, body, end)
      P = end
    }
    if (P < S.length) {
      this.rest = S.slice(P)
      // An entity this long is no transit feed's.
      if (this.rest.length > 4 * 1024 * 1024) throw new Error('not a GTFS-Realtime feed (an entity of 4 MB)')
    }
    S = ''
  }

  end(): Scan {
    if (!this.started) throw new Error('the feed was empty')
    for (const board of this.scan.stops) board.list.sort((a, b) => a.at - b.at)
    return this.scan
  }
}

// "Red | Red Line | #DA291C | Ashmont/Braintree | Alewife": a route id, the
// name to show, its color and where it goes in direction 0 and 1. Lines that
// do not say a part leave it out; # starts a comment.
export function parseLines(text: string): Record<string, LineInfo> {
  const lines: Record<string, LineInfo> = {}
  for (const raw of String(text || '').split('\n')) {
    const row = raw.trim()
    if (!row || row[0] === '#') continue
    const parts = row.split('|').map((part) => part.trim())
    const id = parts[0]
    if (!id) continue
    const color = /^#?[0-9a-fA-F]{6}$/.test(parts[2] || '') ? parts[2].replace('#', '').toUpperCase() : ''
    lines[id] = { label: parts[1] || id, color, to: [parts[3] || '', parts[4] || ''] }
  }
  return lines
}

