import { get } from './app'
import { delayText, nearestInk, INKS, upcoming, whenText } from './board'
import { FeedScanner, parseLines } from './gtfsrt'
import { entur, enturStopId, mbta, tfl } from './providers'

// Saturday 28 November 2026, 15:00 UTC (10:00 in Boston).
const NOW = Date.UTC(2026, 10, 28, 15, 0, 0)
const S = NOW / 1000
const MIN = 60 * 1000

function at<T>(when: number, run: () => T): T {
  const real = Date.now
  Date.now = () => when
  try {
    return run()
  } finally {
    Date.now = real
  }
}

// Every string in a JSX tree, to see what a render says.
function textOf(node: any): string {
  if (node === null || node === undefined || node === false || node === true) return ''
  if (typeof node === 'string' || typeof node === 'number') return String(node)
  if (Array.isArray(node)) return node.map(textOf).join(' ')
  if (typeof node.type === 'function') return textOf(node.type(node.props || {}))
  return textOf(node.props?.children)
}

// ---------------------------------------------------------------- protobuf by hand
const chr = (n: number) => String.fromCharCode(n)
const vint = (value: number): string => {
  let out = ''
  let n = value
  while (n >= 128) {
    out += chr((n % 128) | 128)
    n = Math.floor(n / 128)
  }
  return out + chr(n)
}
// A negative int32, as protobuf writes it: ten bytes of two's complement.
const negative = (value: number): string => {
  let v = (BigInt(1) << BigInt(64)) + BigInt(value)
  let out = ''
  while (v >= BigInt(128)) {
    out += chr(Number(v & BigInt(127)) | 128)
    v = v >> BigInt(7)
  }
  return out + chr(Number(v))
}
const num = (field: number, n: number) => vint(field * 8) + vint(n)
const int = (field: number, n: number) => vint(field * 8) + (n < 0 ? negative(n) : vint(n))
const len = (field: number, body: string) => vint(field * 8 + 2) + vint(body.length) + body
const event = (time: number, extra = '') => num(2, time) + extra
const update = (stop: string, departure: string | null, arrival: string | null = null, extra = '') =>
  len(2, len(4, stop) + (arrival !== null ? len(2, arrival) : '') + (departure !== null ? len(3, departure) : '') + extra)
const tripUpdate = (route: string, direction: number, updates: string[], extra = '') =>
  len(3, len(1, len(1, 'trip-' + route) + len(5, route) + num(6, direction)) + updates.join('') + extra)
const entity = (id: string, body: string) => len(2, len(1, id) + body)
const feed = (entities: string[]) => len(1, len(1, '2.0') + num(3, S - 20)) + entities.join('')

// The body as the runtime hands it to onChunk: bytes 0x80 to 0x9f as Windows-1252's characters.
const CP = [0x20ac, 0x81, 0x201a, 0x192, 0x201e, 0x2026, 0x2020, 0x2021, 0x2c6, 0x2030, 0x160, 0x2039, 0x152, 0x8d, 0x17d, 0x8f,
  0x90, 0x2018, 0x2019, 0x201c, 0x201d, 0x2022, 0x2013, 0x2014, 0x2dc, 0x2122, 0x161, 0x203a, 0x153, 0x9d, 0x17e, 0x178]
const as1252 = (bytes: string) => bytes.replace(/[\x80-\x9f]/g, (c) => chr(CP[c.charCodeAt(0) - 0x80]))
const pieces = (text: string, size: number) => {
  const out: string[] = []
  for (let i = 0; i < text.length; i += size) out.push(text.slice(i, i + size))
  return out
}

const FEED = feed([
  // Red to Alewife (direction 1) from 70076 in 4 min, 2 min late by its delay.
  entity('e1', tripUpdate('Red', 1, [update('70074', event(S + 120)), update('70076', event(S + 240, int(1, 120))), update('70078', null, event(S + 400))])),
  // Red to Ashmont from 70075, a minute early by its timetable time.
  entity('e2', tripUpdate('Red', 0, [update('70075', event(S + 600, num(4, S + 660))), update('70073', event(S + 700))])),
  // A trip that ends at 70075: no departure from there.
  entity('e3', tripUpdate('Red', 0, [update('70077', event(S + 60)), update('70075', null, event(S + 300))])),
  // A deleted entity, and a stop of another board.
  len(2, len(1, 'e4') + num(2, 1) + len(3, len(1, len(5, 'Red')) + update('70075', event(S + 200)))),
  entity('e5', tripUpdate('47', 0, [update('1123', event(S + 900, int(1, -60)))])),
  // A canceled trip (schedule_relationship 3), and one that skips 70076.
  entity('e6', len(3, len(1, len(5, 'Orange') + num(4, 3)) + update('70076', event(S + 1200)))),
  entity('e7', tripUpdate('Red', 1, [update('70076', event(S + 1500), null, num(5, 1)), update('70080', event(S + 1600))])),
])

describe('a GTFS-Realtime feed read as it streams in', () => {
  it('finds the departures at the stops asked for, whatever the pieces', () => {
    const lines = parseLines('Red | Red | #da291c | Ashmont/Braintree | Alewife\n# a comment\n47 | 47')
    for (const size of [1, 7, 64, 100000]) {
      const scanner = new FeedScanner([['70075', '70076'], ['1123']], lines, NOW)
      for (const piece of pieces(as1252(FEED), size)) scanner.push(piece)
      const scan = scanner.end()
      expect(scan.entities).toBe(7)
      expect(scan.feedTime).toBe(S - 20)
      const here = scan.stops[0].list
      expect(here.map((d) => [d.line, d.to, d.at, d.delay, d.gone])).toEqual([
        ['Red', 'Alewife', (S + 240) * 1000, 120, false],
        ['Red', 'Ashmont/Braintree', (S + 600) * 1000, -60, false],
        ['Orange', '', (S + 1200) * 1000, null, true],
        ['Red', 'Alewife', (S + 1500) * 1000, null, true],
      ])
      expect(here[0].color).toBe('DA291C')
      expect(scan.stops[1].list.map((d) => [d.line, d.delay])).toEqual([['47', -60]])
    }
  })

  it('reads a body that is one character a byte, and refuses what is no feed', () => {
    const scanner = new FeedScanner([['70075']], {}, NOW)
    scanner.push(FEED, true)
    expect(scanner.end().stops[0].list.length).toBe(1)
    expect(() => new FeedScanner([['1']], {}, NOW).push('<html><body>Not found</body></html>')).toThrow('not a GTFS-Realtime feed')
    expect(() => new FeedScanner([['1']], {}, NOW).end()).toThrow('the feed was empty')
  })

  it('reads the lines table', () => {
    expect(parseLines('Green-B | B | 00843D | Boston College | Government Center\nX|')).toEqual({
      'Green-B': { label: 'B', color: '00843D', to: ['Boston College', 'Government Center'] },
      X: { label: 'X', color: '', to: ['', ''] },
    })
  })
})

// ---------------------------------------------------------------- the providers

const route = (id: string, color: string, text: string, short: string, long: string, type: number) => ({
  type: 'route', id, attributes: { color, text_color: text, short_name: short, long_name: long, type },
})
const rel = (type: string, id: string | null) => ({ data: id ? { type, id } : null })
const prediction = (id: string, departure: string | null, sr: string | null, routeId: string, trip: string, schedule: string | null) => ({
  type: 'prediction', id,
  attributes: { departure_time: departure, schedule_relationship: sr },
  relationships: { route: rel('route', routeId), trip: rel('trip', trip), stop: rel('stop', '70075'), schedule: rel('schedule', schedule) },
})
const schedule = (id: string, departure: string | null, routeId: string, trip: string) => ({
  type: 'schedule', id, attributes: { departure_time: departure },
  relationships: { route: rel('route', routeId), trip: rel('trip', trip), stop: rel('stop', '1123') },
})
const PREDICTIONS = {
  data: [
    // Sorted by departure, the canceled and the terminating come first.
    prediction('p3', null, 'CANCELLED', 'Red', 't3', 's3'),
    prediction('p2', null, null, 'Red', 't2', 's2'),
    prediction('p1', '2026-11-28T10:04:00-05:00', null, 'Red', 't1', 's1'),
  ],
  included: [
    route('Red', 'DA291C', 'FFFFFF', '', 'Red Line', 1),
    { type: 'trip', id: 't1', attributes: { headsign: 'Alewife' } },
    { type: 'trip', id: 't3', attributes: { headsign: 'Ashmont' } },
    { type: 'stop', id: '70075', attributes: { name: 'Park Street', platform_code: null } },
    { type: 'schedule', id: 's1', attributes: { departure_time: '2026-11-28T10:02:00-05:00' } },
    { type: 'schedule', id: 's3', attributes: { departure_time: '2026-11-28T10:20:00-05:00' } },
  ],
}
const SCHEDULES = {
  data: [
    schedule('s12', '2026-11-28T10:03:00-05:00', 'Red', 't12'),
    schedule('s1', '2026-11-28T10:02:00-05:00', 'Red', 't1'),
    schedule('s10', '2026-11-28T10:30:00-05:00', '47', 't10'),
  ],
  included: [
    route('47', 'FFC72C', '000000', '47', 'Central Square - Broadway', 3),
    route('Red', 'DA291C', 'FFFFFF', '', 'Red Line', 1),
    { type: 'trip', id: 't10', attributes: { headsign: 'Broadway Station' } },
    { type: 'trip', id: 't12', attributes: { headsign: 'Alewife' } },
  ],
}

describe('MBTA', () => {
  it('reads predictions with their delays and cancellations, and the timetable around them', () => {
    const http = mock.httpRequest((url: string) => {
      if (url.indexOf('/predictions?') > 0) return mock.json(PREDICTIONS)
      if (url.indexOf('/schedules?') > 0) return mock.json(SCHEDULES)
      return mock.json({}, 404)
    })
    const board = mbta('place-pktrm', NOW)
    expect(board.name).toBe('Park Street')
    expect(board.list.map((d) => [d.line, d.color, d.text, d.to, (d.at - NOW) / MIN, d.live, d.delay, d.gone])).toEqual([
      ['Red', 'DA291C', 'FFFFFF', 'Alewife', 4, true, 120, false],
      ['Red', 'DA291C', 'FFFFFF', 'Ashmont', 20, false, null, true],
      ['47', 'FFC72C', '000000', 'Broadway Station', 30, false, null, false],
    ])
    // The timetable from Boston's 10:00, with the stop's id.
    const asked = String(http.calls[1][0])
    expect(asked).toContain('filter%5Bmin_time%5D=10:00')
    expect(asked).toContain('filter%5Bstop%5D=place-pktrm')
  })
})

describe('Entur', () => {
  it('looks a stop up by its name, and reads its calls', () => {
    const http = mock.httpRequest((url: string, options: any) => {
      if (url.indexOf('/geocoder/') > 0) {
        return mock.json({ features: [{ properties: { id: 'NSR:StopPlace:58366', name: 'Jernbanetorget', label: 'Jernbanetorget, Oslo' } }] })
      }
      expect(options.method).toBe('POST')
      expect(options.headers['ET-Client-Name']).toBe('frameos-transitdepartures')
